CREATE TABLE "Attachment" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "incident_id" integer NOT NULL,
    "storage_key" varchar(255) NOT NULL UNIQUE,
    "file_type" varchar(50) NOT NULL,
    "file_size" bigint NOT NULL,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "fk_attachment_incident"
        FOREIGN KEY ("incident_id") REFERENCES "Incident" ("id") ON DELETE CASCADE,
    CONSTRAINT "ck_attachment_file_size_positive"
        CHECK ("file_size" > 0)
);

-- Supports loading the attachments of one incident in creation order.
CREATE INDEX "idx_attachment_incident_id_id"
    ON "Attachment" ("incident_id", "id");
